SELECT CAST(COUNT(DISTINCT CASE WHEN a.readmit_flag = 1 THEN a.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS readmission_rate, AVG(CASE WHEN a.readmit_flag = 1 THEN i.los END) AS avg_los_readmitted, AVG(CASE WHEN a.readmit_flag = 0 THEN i.los END) AS avg_los_non_readmitted, SUM(CASE WHEN a.readmit_flag = 1 THEN CASE WHEN i.los > 9 THEN 1 ELSE 0 END) AS patients_with_long_los FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN icustays i ON a.stay_id = i.stay_id WHERE p.gender = 'M' AND p.insurance = 'Medicare' AND EXTRACT(YEAR FROM a.admittime) BETWEEN 2015 AND 2016 AND a.admission_type = 'ED' AND i.stay_type = 'ICU' AND i.los <= 9 AND (a.dischtime - a.admittime) <= 30 AND p.anchor_age BETWEEN 60 AND 70 AND p.anchor_year BETWEEN 2015 AND 2016 AND (SELECT COUNT(*) FROM admissions WHERE subject_id = a.subject_id AND readmit_flag = 1) > 0;